def total(*nums):
    return sum(nums)

def describe(**info):
    return ', '.join(f'{k}={info[k]}' for k in sorted(info))

def mixed(a, b, *rest, **extra):
    return {'a': a, 'b': b, 'rest': rest, 'extra': extra}

print(total())
print(total(1, 2, 3, 4))
print(describe(name='小明', age=18))
print(mixed(1, 2, 3, 4, x=5))
